// Функция для парсинга XML в JSON (ручной парсер)
function parseXMLToJSON(xmlText) {
    const result = {
        items: []
    };

    try {
        // Извлекаем все item'ы из XML
        const itemRegex = /<item>([\s\S]*?)<\/item>/g;
        const items = [];
        let match;

        while ((match = itemRegex.exec(xmlText)) !== null) {
            items.push(match[1]);
        }

        // Парсим каждый item
        for (const itemXml of items) {
            const item = {};

            // Извлекаем title
            const titleMatch = itemXml.match(/<title>([\s\S]*?)<\/title>/);
            if (titleMatch) item.title = titleMatch[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim();

            // Извлекаем description
            const descMatch = itemXml.match(/<description>([\s\S]*?)<\/description>/);
            if (descMatch) item.description = descMatch[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim();

            // Извлекаем author
            const authorMatch = itemXml.match(/<author>([\s\S]*?)<\/author>/);
            if (authorMatch) item.author = authorMatch[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim();

            // Извлекаем link
            const linkMatch = itemXml.match(/<link>([\s\S]*?)<\/link>/);
            if (linkMatch) item.link = linkMatch[1].trim();

            // Извлекаем guid (уникальный ID)
            const guidMatch = itemXml.match(/<guid>([\s\S]*?)<\/guid>/);
            if (guidMatch) item.id = guidMatch[1].trim();

            // Извлекаем pubDate
            const dateMatch = itemXml.match(/<pubDate>([\s\S]*?)<\/pubDate>/);
            if (dateMatch) item.pubDate = dateMatch[1].trim();

            // Извлекаем город из title или description
            const cityMatch = item.title?.match(/\((.*?)\)/) || item.description?.match(/\((.*?)\)/);
            if (cityMatch) item.city = cityMatch[1];

            // Добавляем полный контент для фильтрации
            item.content = (item.title || '') + ' ' + (item.description || '');

            result.items.push(item);
        }
    } catch (e) {
        console.error('Ошибка парсинга XML:', e);
    }

    return result;
}

// Получаем входные данные
const inputData = $input.all();

// Здесь будет результат
let allVacancies = [];

// Обрабатываем каждый входной элемент
for (const item of inputData) {
    // Получаем XML текст из поля data
    const xmlText = item.json.data;

    if (xmlText && typeof xmlText === 'string') {
        // Парсим XML в JSON
        const parsed = parseXMLToJSON(xmlText);
        allVacancies = allVacancies.concat(parsed.items);
    }
}

// Преобразуем массив вакансий в формат, понятный n8n
return allVacancies.map(vacancy => ({ json: vacancy }));

// Функция для экранирования спецсимволов MarkdownV2
function escapeMarkdown(text) {
    if (!text) return '';

    // Символы, которые нужно экранировать в MarkdownV2
    const specialChars = ['_', '*', '[', ']', '(', ')', '~', '`', '>', '#', '+', '-', '=', '|', '{', '}', '.', '!'];

    let escaped = String(text);
    for (const char of specialChars) {
        escaped = escaped.replace(new RegExp('\\' + char, 'g'), '\\' + char);
    }

    return escaped;
}

// Получаем все вакансии
const items = $input.all();

// Если вакансий нет, отправляем специальное сообщение
if (items.length === 0) {
    return [{
        json: {
            message: "😔 Сегодня подходящих вакансий не найдено. Проверю завтра!"
        }
    }];
}

// Формируем текст сообщения
let messageText = "🚀 *Дайджест вакансий " + new Date().toLocaleDateString('ru-RU') + "*\n\n";

// Добавляем каждую вакансию в сообщение
for (let i = 0; i < items.length; i++) {
    const item = items[i].json;

    // Экранируем все текстовые поля
    const title = escapeMarkdown(item.title || 'Без названия');
    const author = escapeMarkdown(item.author || 'Не указана');
    let description = escapeMarkdown(item.content || item.description || '');

    // Обрезаем описание
    description = description.replace(/\n/g, ' ').substring(0, 200);
    if (description.length === 200) description += '...';

    // Номер вакансии
    messageText += `*${i + 1}. ${title}*\n`;
    messageText += `🏢 ${author}\n`;
    messageText += `⭐ Рейтинг: ${item.rating || 0}\n`;

    // Описание
    messageText += `📝 ${description}\n`;

    // Добавляем источник
    if (item.source === 'hh.ru') {
        messageText += `📌 Источник: HeadHunter\n`;
    } else {
        messageText += `📌 Источник: Хабр Карьера\n`;
    }

    // Ссылка (не экранируем, так как она в специальном формате)
    const link = item.link || '';
    messageText += `🔗 [Перейти к вакансии](${link})\n`;

    // Разделитель между вакансиями (кроме последней)
    if (i < items.length - 1) {
        messageText += `\n---\n\n`;
    }
}

// Возвращаем одно сообщение
return [{
    json: {
        message: messageText
    }
}];

