const items = $input.all();
const newItems = [];

// Ключевые слова для ранжирования (чем больше, тем лучше)
const keywords = [
    'ии', 'нейросет', 'искусственный интеллект', 'gpt', // AI
    'no-code', 'nocode', 'low-code', // No-code
    'автоматизац', 'оптимизац', 'эффективност', // Автоматизация
    'проектирован', 'project', 'pm', 'agile', 'scrum', 'канбан', // Управление
    'стажер', 'помощник', 'младший', 'junior', 'trainee' // Дублеры позиции
];

for (const item of items) {
    let rating = 0;
    const content = item.json.content ? item.json.content.toLowerCase() : '';
    const title = item.json.title ? item.json.title.toLowerCase() : '';

    // Ищем ключевые слова в названии и описании
    for (const word of keywords) {
        // Даем больше баллов за совпадение в названии
        if (title.includes(word)) {
            rating += 3;
        } else if (content.includes(word)) {
            rating += 1;
        }
    }

    // Добавляем рейтинг в данные
    newItems.push({
        json: {
            ...item.json,
            rating: rating // Добавляем поле с рейтингом
        }
    });
}

// Сортируем по убыванию рейтинга (от больших к меньшим)
newItems.sort((a, b) => b.json.rating - a.json.rating);

return newItems;

